#include <Wire.h>

// Настройки пинов (для Arduino Nano ESP32)
#define SDA_PIN A4
#define SCL_PIN A5
#define OLED_ADDR 0x3C

// Минимальный шрифт 5x7 для букв (H, e, l, o, T, i, m, пробел)
const uint8_t font[][5] = {
  {0x7F, 0x08, 0x08, 0x08, 0x7F}, // H
  {0x38, 0x54, 0x54, 0x54, 0x18}, // e
  {0x00, 0x41, 0x7F, 0x40, 0x00}, // l
  {0x38, 0x44, 0x44, 0x44, 0x38}, // o
  {0x7F, 0x40, 0x40, 0x40, 0x40}, // T
  {0x00, 0x44, 0x7D, 0x40, 0x00}, // i
  {0x7C, 0x04, 0x18, 0x04, 0x78}, // m
  {0x00, 0x00, 0x00, 0x00, 0x00}  // пробел
};

void setup() {
  Wire.begin(SDA_PIN, SCL_PIN);

  // Инициализация дисплея SSD1306
  Wire.beginTransmission(OLED_ADDR);
  Wire.write(0x00); // Команды
  Wire.write(0xAE); // Выключить дисплей
  Wire.write(0xD5); Wire.write(0x80); // Частота
  Wire.write(0xA8); Wire.write(0x3F); // Multiplex 64
  Wire.write(0xD3); Wire.write(0x00); // Смещение
  Wire.write(0x40); // Начало строки
  Wire.write(0x8D); Wire.write(0x14); // Включить зарядный насос
  Wire.write(0x20); Wire.write(0x00); // Режим памяти
  Wire.write(0xA1); // Сегменты
  Wire.write(0xC8); // COM сканирование
  Wire.write(0xDA); Wire.write(0x12); // Конфигурация COM
  Wire.write(0x81); Wire.write(0xCF); // Контраст
  Wire.write(0xD9); Wire.write(0xF1); // Pre-charge
  Wire.write(0xDB); Wire.write(0x40); // VCOM
  Wire.write(0xA4); // Из RAM
  Wire.write(0xA6); // Нормальный режим
  Wire.write(0xAF); // Включить дисплей
  Wire.endTransmission();

  // Очистка экрана
  for (uint8_t page = 0; page < 8; page++) {
    Wire.beginTransmission(OLED_ADDR);
    Wire.write(0x00); Wire.write(0xB0 + page); // Страница
    Wire.write(0x00); Wire.write(0x10); // Колонка 0
    Wire.endTransmission();
    Wire.beginTransmission(OLED_ADDR);
    Wire.write(0x40); // Данные
    for (uint8_t i = 0; i < 128; i++) Wire.write(0x00); // Черный цвет
    Wire.endTransmission();
  }

  // Вывод текста "Hello Tim" на 2-й строке (y=2)
  String text = "Hello Tim";
  for (uint8_t c = 0; c < text.length(); c++) {
    uint8_t charIndex = 0;
    if (text[c] == 'H') charIndex = 0;
    else if (text[c] == 'e') charIndex = 1;
    else if (text[c] == 'l') charIndex = 2;
    else if (text[c] == 'o') charIndex = 3;
    else if (text[c] == 'T') charIndex = 4;
    else if (text[c] == 'i') charIndex = 5;
    else if (text[c] == 'm') charIndex = 6;
    else charIndex = 7; // Пробел

    Wire.beginTransmission(OLED_ADDR);
    Wire.write(0x00); // Команда
    Wire.write(0xB0 + 2); // 3-я строка (страницы 0-7)
    Wire.write(0x00 + ((c * 6) & 0x0F)); // Младшие 4 бита колонки
    Wire.write(0x10 + ((c * 6) >> 4));   // Старшие 4 бита колонки
    Wire.endTransmission();

    Wire.beginTransmission(OLED_ADDR);
    Wire.write(0x40); // Данные
    for (uint8_t i = 0; i < 5; i++) {
      Wire.write(font[charIndex][i]);
    }
    Wire.write(0x00); // Пробел между буквами
    Wire.endTransmission();
  }
}

void loop() {}
